const assert = require('node:assert/strict');

        const { Ledger } = require('../.build/ledger');
        const { PaymentService } = require('../.build/service');
        const { Transient } = require('../.build/transport');
        async function main() {
          const ledger = new Ledger(); const receipts = [];
          const service = new PaymentService(ledger, { acknowledge: async r => { receipts.push(r); } });
          assert.deepEqual(await service.pay('shop', 'sale', 123), { id: 1, tenant: 'shop', key: 'sale', cents: 123 });
          assert.equal(ledger.entries.length, 1); assert.equal(receipts.length, 1);
          await assert.rejects(service.pay('shop', 'bad', 0), /invalid payment/);

          // Retries after Transient acknowledgements: one debit, same receipt forwarded each time.
          {
            const l = new Ledger(); const seen = []; let calls = 0;
            const s = new PaymentService(l, { acknowledge: async r => { seen.push(r); if (calls++ < 2) throw new Transient('later'); } });
            const r = await s.pay('t', 'k', 7, 3);
            assert.equal(calls, 3); assert.equal(l.entries.length, 1);
            assert.equal(seen.length, 3); for (const x of seen) assert.strictEqual(x, r);
          }

          // Exhaustion rethrows the final Transient unchanged.
          {
            const l = new Ledger(); let calls = 0; const err = new Transient('down');
            const s = new PaymentService(l, { acknowledge: async () => { calls++; throw err; } });
            await assert.rejects(s.pay('t', 'k', 7, 2), e => e === err);
            assert.equal(calls, 2); assert.equal(l.entries.length, 1);
          }

          // Non-Transient acknowledgement errors are not retried.
          {
            const l = new Ledger(); let calls = 0; const err = new Error('boom');
            const s = new PaymentService(l, { acknowledge: async () => { calls++; throw err; } });
            await assert.rejects(s.pay('t', 'k', 7, 5), e => e === err);
            assert.equal(calls, 1);
          }

          // Equal replay returns the original receipt without another debit.
          {
            const l = new Ledger(); const acks = []; const s = new PaymentService(l, { acknowledge: async r => { acks.push(r); } });
            const a = await s.pay('t', 'k', 9); const b = await s.pay('t', 'k', 9);
            assert.strictEqual(a, b); assert.equal(l.entries.length, 1); assert.equal(acks.length, 2);
          }

          // Concurrent equal calls debit once and share the receipt.
          {
            const l = new Ledger(); const s = new PaymentService(l, { acknowledge: async () => {} });
            const [a, b] = await Promise.all([s.pay('t', 'k', 9), s.pay('t', 'k', 9)]);
            assert.strictEqual(a, b); assert.equal(l.entries.length, 1);
          }

          // Same tenant/key with a different amount: key conflict, no debit, no ack.
          {
            const l = new Ledger(); let acks = 0; const s = new PaymentService(l, { acknowledge: async () => { acks++; } });
            await s.pay('t', 'k', 9);
            await assert.rejects(s.pay('t', 'k', 10), /^Error: key conflict$/);
            assert.equal(l.entries.length, 1); assert.equal(acks, 1);
          }

          // Scoping: same key under other tenants is independent; no delimiter collisions.
          {
            const l = new Ledger(); const s = new PaymentService(l, { acknowledge: async () => {} });
            await s.pay('a', 'b:c', 1); await s.pay('a:b', 'c', 2); await s.pay('b', 'c', 3);
            await s.pay('a', 'b:c', 1);
            assert.equal(l.entries.length, 3);
            await assert.rejects(s.pay('a:b', 'c', 5), /key conflict/);
          }

          // Invalid input throws before any ledger or transport action.
          {
            const bad = [
              ['', 'k', 1], ['t', '', 1], [undefined, 'k', 1], ['t', undefined, 1], [5, 'k', 1],
              ['t', 'k', 0], ['t', 'k', -1], ['t', 'k', 1.5], ['t', 'k', '5'], ['t', 'k', NaN], ['t', 'k', Infinity],
            ];
            for (const args of bad) {
              let touched = 0;
              const l = new Ledger(); const apply = l.apply.bind(l); l.apply = (...x) => { touched++; return apply(...x); };
              const s = new PaymentService(l, { acknowledge: async () => { touched++; } });
              await assert.rejects(s.pay(...args), /^Error: invalid payment$/, JSON.stringify(args));
              assert.equal(touched, 0); assert.equal(l.entries.length, 0);
            }
            for (const attempts of [0, 6, 1.5, '3', NaN, -1]) {
              let touched = 0;
              const l = new Ledger(); const apply = l.apply.bind(l); l.apply = (...x) => { touched++; return apply(...x); };
              const s = new PaymentService(l, { acknowledge: async () => { touched++; } });
              await assert.rejects(s.pay('t', 'k', 1, attempts), /^Error: invalid payment$/, String(attempts));
              assert.equal(touched, 0);
            }
          }

          // Boundary attempts values are accepted.
          {
            for (const attempts of [1, 5]) {
              const l = new Ledger(); const s = new PaymentService(l, { acknowledge: async () => {} });
              await s.pay('t', String(attempts), 1, attempts);
            }
            const l = new Ledger(); let calls = 0; const s = new PaymentService(l, { acknowledge: async () => { calls++; throw new Transient('x'); } });
            await assert.rejects(s.pay('t', 'k', 1, 1), Transient);
            assert.equal(calls, 1);
          }
        }
        module.exports = main();
EOF
